import { forwardRef, type InputHTMLAttributes, type ReactNode } from 'react';

export type InputProps = {
  error?: boolean;
  iconLeft?: ReactNode;
  iconRight?: ReactNode;
  className?: string;
} & Omit<InputHTMLAttributes<HTMLInputElement>, 'className'>;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export const Input = forwardRef<HTMLInputElement, InputProps>(
  ({ error = false, iconLeft, iconRight, className, ...props }, ref) => {
    const hasIcons = iconLeft || iconRight;

    if (hasIcons) {
      return (
        <div
          className={cn(
            'input-group',
            error && 'input-group--error',
            props.disabled && 'input-group--disabled',
            className,
          )}
        >
          {iconLeft && <span className="input-group__icon">{iconLeft}</span>}
          <input
            ref={ref}
            className="input-group__input"
            aria-invalid={error || undefined}
            {...props}
          />
          {iconRight && <span className="input-group__icon">{iconRight}</span>}
        </div>
      );
    }

    return (
      <input
        ref={ref}
        className={cn('input', className)}
        aria-invalid={error || undefined}
        {...props}
      />
    );
  },
);

Input.displayName = 'Input';

/* -------------------------------------------------------------------------
   Input

   Base text input. Height matches Button m (40px).
   Used standalone or inside Field wrapper.
   Colors matched to Figma atom-text-field.

   States: default, focus, disabled, error
   ------------------------------------------------------------------------- */

.input {
  display: flex;
  width: 100%;
  height: 2.5rem;
  padding: 0 var(--spacing-2);
  border: var(--stroke-thin) solid var(--border-input);
  border-radius: var(--radius-md);
  background-color: var(--background);
  color: var(--foreground);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  line-height: 1;
  outline: none;
  transition:
    border-color var(--duration-150) var(--easing-out),
    box-shadow var(--duration-150) var(--easing-out);
}

.input::placeholder {
  color: var(--placeholder);
}

.input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 var(--stroke-medium) var(--focus-ring-color);
}

.input:disabled {
  background-color: var(--muted);
  border-color: var(--muted);
  color: var(--muted-foreground);
  cursor: not-allowed;
  opacity: 1;
}

.input[aria-invalid="true"] {
  border-color: var(--destructive);
  box-shadow: 0 0 var(--stroke-medium) 0 var(--focus-ring-error-color);
}

.input[aria-invalid="true"]:focus {
  border-color: var(--destructive);
  box-shadow: 0 0 0 var(--stroke-medium) var(--focus-ring-error-color);
}

/* File input */
.input[type="file"] {
  padding: 0;
}

.input[type="file"]::file-selector-button {
  height: 100%;
  padding: 0 var(--spacing-3);
  border: none;
  border-right: var(--stroke-thin) solid var(--border-input);
  background-color: var(--muted);
  color: var(--foreground);
  font-family: inherit;
  font-size: inherit;
  font-weight: var(--font-weight-medium);
  cursor: pointer;
}

/* ---- Input Group (input with leading/trailing icons) ---- */

.input-group {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
  width: 100%;
  height: 2.5rem;
  padding: 0 var(--spacing-2);
  border: var(--stroke-thin) solid var(--border-input);
  border-radius: var(--radius-md);
  background-color: var(--background);
  transition:
    border-color var(--duration-150) var(--easing-out),
    box-shadow var(--duration-150) var(--easing-out);
}

.input-group:focus-within {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 var(--stroke-medium) var(--focus-ring-color);
}

.input-group--error {
  border-color: var(--destructive);
  box-shadow: 0 0 var(--stroke-medium) 0 var(--focus-ring-error-color);
}

.input-group--error:focus-within {
  border-color: var(--destructive);
  box-shadow: 0 0 0 var(--stroke-medium) var(--focus-ring-error-color);
}

.input-group--disabled {
  background-color: var(--muted);
  border-color: var(--muted);
  cursor: not-allowed;
}

.input-group__input {
  flex: 1;
  min-width: 0;
  border: none;
  background: none;
  color: var(--foreground);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  line-height: 1;
  outline: none;
  padding: 0;
}

.input-group__input::placeholder {
  color: var(--placeholder);
}

.input-group__input:disabled {
  color: var(--muted-foreground);
  cursor: not-allowed;
}

.input-group__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
  color: var(--placeholder);
}

.input-group__icon svg {
  width: 100%;
  height: 100%;
}

.input-group--disabled .input-group__icon {
  color: var(--muted-foreground);
}
